end


-- SRCHUB_SHARED_ASSETS_BEGIN
do
    _G.RealNow = _G.RealNow or os.clock
    local IconVector2D = import("Vector2D")
    local function GetConfigPaths(fileName)
        local paths = {
            "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                .. fileName,
            "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                .. fileName,
            "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                .. fileName,
            "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                .. fileName,
            "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                .. fileName,
            "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
        }
        pcall(function()
            if os and os.getenv then
                local homeDir = os.getenv("HOME")
                if homeDir and homeDir ~= "" then
                    table.insert(paths, 1, homeDir .. "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
                end
            end
        end)
        return paths
    end
    _G.MWIconB64 = {
        ["brand_logo"] = "",
        ["edge_marker"] = "",
        ["ui_close"] = "",
        ["ui_fill_corner"] = "",
    }
    _G._MWIconTex = {}

    function _G.MWB64Decode(b64)
        local out = {}
        local map = _G._MWB64Map
        if not map then
            map = {}
            local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            for i = 1, 64 do
                map[chars:byte(i)] = i - 1
            end
            _G._MWB64Map = map
        end
        local n, i = #b64, 1
        while i <= n do
            local a, b, c, d =
                map[b64:byte(i)], map[b64:byte(i + 1)], map[b64:byte(i + 2)], map[b64:byte(i + 3)]
            if a == nil or b == nil then
                break
            end
            local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
            out[#out + 1] = string.char(math.floor(v / 65536) % 256)
            if c ~= nil then
                out[#out + 1] = string.char(math.floor(v / 256) % 256)
            end
            if d ~= nil then
                out[#out + 1] = string.char(v % 256)
            end
            i = i + 4
        end
        return table.concat(out)
    end
    function _G.MWIconTexture(key)
        local cached = _G._MWIconTex[key]
        if cached ~= nil then
            if cached == false then
                return nil
            end
            if type(cached) == "number" then
                if _G.RealNow() < cached then
                    return nil
                end
            elseif slua.isValid(cached) then
                return cached
            end
            _G._MWIconTex[key] = nil
        end
        local b64 = _G.MWIconB64[key]
        if not b64 then
            _G._MWIconTex[key] = false
            return nil
        end
        local tex = nil
        local written = {}
        pcall(function()
            local bytes = _G.MWB64Decode(b64)
            _G._MWIconLoadN = (_G._MWIconLoadN or 0) + 1
            local fname = "mw_icon_" .. key .. "_" .. tostring(_G._MWIconLoadN) .. ".png"
            for _, path in ipairs(GetConfigPaths(fname)) do
                local f = io.open(path, "wb")
                if f then
                    local wrote = pcall(f.write, f, bytes)
                    local closed = pcall(f.close, f)
                    if wrote and closed then
                        written[1] = path
                        break
                    end
                    pcall(os.remove, path)
                end
            end
            local LT = import("LoadTexture")
            local BH = import("BusinessHelper")
            if not LT then
                return
            end
            for _, path in ipairs(written) do
                local cands = { path }
                pcall(function()
                    if BH and BH.GetMobileBasePath then
                        local mp = BH.GetMobileBasePath(path)
                        if mp and mp ~= "" then
                            cands[#cands + 1] = mp
                        end
                    end
                end)
                for _, cp in ipairs(cands) do
                    pcall(function()
                        tex = LT.GetTexture2DFromDiskFile(cp)
                    end)
                    if tex and slua.isValid(tex) then
                        return
                    end
                    tex = nil
                end
            end
        end)
        for _, path in ipairs(written) do
            pcall(os.remove, path)
        end
        if tex and slua.isValid(tex) then
            _G._MWIconTex[key] = tex
            return tex
        end
        _G._MWIconTex[key] = _G.RealNow() + 3.0
        return nil
    end
    function _G.MWIconImageAt(canvas, x, y, w, h, key, ax, ay, z)
        local tex = _G.MWIconTexture(key)
        if not tex then
            return nil
        end
        local img = nil
        pcall(function()
            img = CGame:NewObjectFromPath("/Script/UMG.Image", canvas)
        end)
        if not img or not slua.isValid(img) then
            return nil
        end
        local ok = false
        pcall(function()
            img:SetBrushFromTexture(tex, false)
            ok = true
        end)
        if not ok then
            return nil
        end
        pcall(function()
            img:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
        end)
        local slot = nil
        pcall(function()
            slot = canvas:AddChildToCanvas(img)
        end)
        if slot then
            pcall(function()
                slot:SetAutoSize(false)
            end)
            pcall(function()
                slot:SetSize(IconVector2D(w, h))
            end)
            pcall(function()
                slot:SetPosition(IconVector2D(x, y))
            end)
            pcall(function()
                slot:SetAlignment(IconVector2D(ax or 0, ay or 0))
            end)
            pcall(function()
                slot:SetZOrder(z or 0)
            end)
        end
        local marker = rawget(_G, "PlayerMapMarker")
        if type(marker) ~= "table" then
            marker = {}
            rawset(_G, "PlayerMapMarker", marker)
        end
        marker._ProtectedWidgetStrs = marker._ProtectedWidgetStrs or {}
        marker._ProtectedWidgetStrs[tostring(img)] = true
        return { w = img, slot = slot, key = key }
    end
end
-- SRCHUB_SHARED_ASSETS_END

