local function Valid(w)
    if w == nil then
        return false
    end
    local ok, valid = pcall(slua.isValid, w)
    return ok and valid == true
end
local function objectToken(object)
    if object == nil then
        return "nil"
    end
    local ok, token = pcall(tostring, object)
    return ok and token or "unavailable"
end
_G.MWWidgetLive = Valid
local function finite(v)
    return type(v) == "number" and v == v and math.abs(v) < 1e9
end
local function now()
    return _G.RealNow and _G.RealNow() or os.clock()
end
local Clock = import("GameplayStatics")
local clockState = rawget(_G, "__SRCHUBTravelClock") or { value = nil }
_G.__SRCHUBTravelClock = clockState
_G.RealNow = function()
    local cpu = os.clock()
    local world, raw
    if Clock and Clock.GetRealTimeSeconds and slua.getWorld then
        local got, current = pcall(slua.getWorld)
        world = got and current or nil
        if world then
            local ok, value = pcall(Clock.GetRealTimeSeconds, world)
            if ok and finite(value) and value >= 0 then
                raw = value
            end
        end
    end
    local token = objectToken(world)
    if clockState.value == nil then
        clockState.value = raw or cpu
    elseif raw and clockState.raw and token == clockState.worldToken and raw >= clockState.raw then
        clockState.value = clockState.value + raw - clockState.raw
    else
        clockState.value = clockState.value + math.max(0, cpu - (clockState.cpu or cpu))
    end

    clockState.worldToken, clockState.raw, clockState.cpu = token, raw, cpu
    return clockState.value
end
