function _G.GetEnemyTargetsFromActors(radius)
    local result = {}
    local player = GameplayData.GetPlayerCharacter()
    if not Valid(player) then
        return result
    end
    for _, actor in pairs(Core.Pawns) do
        local team = Valid(actor) and Core.TeamID(actor)
        local mine = Core.TeamID(player)
        if
            Valid(actor)
            and actor ~= player
            and (not team or not mine or team ~= mine)
            and actor.HealthStatus ~= 2
        then
            local distance = player:GetDistanceTo(actor)
            if finite(distance) and distance <= (tonumber(radius) or 0) then
                result[#result + 1] = actor
            end
        end
    end
    return result
end
function _G.XthrlenAimDistTo(a, b)
    local p, q = a:K2_GetActorLocation(), b:K2_GetActorLocation()
    local x, y, z = p.X - q.X, p.Y - q.Y, p.Z - q.Z
    return math.sqrt(x * x + y * y + z * z)
end
function Core.Report(key, message)
    Core.Errors[key] = tostring(message)
end
local function safe(key, fn, ...)
    local ok, result = pcall(fn, ...)

    if not ok then
        Core.Report(key, result)
    else
        Core.Errors[key] = nil
    end
    return ok, result
end
local function paths(name)
    local result = {}
    for _, pkg in ipairs({
        "com.pubg.imobile",
        "com.tencent.ig",
        "com.pubg.krmobile",
        "com.vng.pubgmobile",
        "com.rekoo.pubgm",
    }) do
        result[#result + 1] = "/storage/emulated/0/Android/data/" .. pkg .. "/files/" .. name
    end
    return result
end
function _G.SaveModSettings()
    local lines = {}
    for key, value in pairs(_G.MWConfig) do
        lines[#lines + 1] = "c." .. key .. "=" .. tostring(value)
    end
    for key, value in pairs(_G.MWState.CustomTextData) do
        if finite(value) then
            lines[#lines + 1] = "t." .. key .. "=" .. tostring(value)
        end
    end
    table.sort(lines)
    for _, path in ipairs(paths("MEOW_MINIMAL.cfg")) do
        local f = io.open(path .. ".tmp", "wb")
        if f then
            local ok, written = pcall(f.write, f, table.concat(lines, "\n"))
            local closed = pcall(f.close, f)
            if ok and written and closed and os.rename(path .. ".tmp", path) then
                return true
            end
        end
    end
    return false
end
function Core.LoadSettings()
    local defaults = _G.MWDefaultConfig()
    for _, path in ipairs(paths("MEOW_MINIMAL.cfg")) do
        local f = io.open(path, "rb")
        if f then
            local text = f:read(65537)
            f:close()
            if #text <= 65536 then
                for scope, key, raw in text:gmatch("([ct])%.([%w_]+)=([^\r\n]+)") do
                    local target = scope == "c" and _G.MWConfig or _G.MWState.CustomTextData
                    local reference = scope == "c" and defaults[key] or target[key]
                    if scope == "c" and key == "EspMaxDistance" then
                        target[key] = defaults.EspMaxDistance
                    elseif type(reference) == "boolean" and (raw == "true" or raw == "false") then
                        target[key] = raw == "true"
                    elseif type(reference) == "number" then
                        local n = tonumber(raw)
                        if finite(n) then
                            target[key] = math.max(0, math.min(1000, n))
                        end
                    end
                end
            end
            return
        end
    end
end
function Core.ResolveCanvas()
    local time = now()
    if time < (Core.NextCanvasCheck or 0) and Valid(Core.Canvas) then
        return Core.Canvas
    end
    Core.NextCanvasCheck = time + 0.25
    local tools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
    local ui = tools.GetMainControlBaseUI()
    local canvas = Valid(ui) and (ui.CanvasPanel_0 or ui.CanvasPanel_42) or nil
    if not Valid(canvas) then
        return nil
    end
    local canvasToken = objectToken(canvas)
    if canvasToken ~= Core.CanvasToken or not Valid(Core.Canvas) then
        if Core.Clear then
            Core.Clear()
        end
        if LM and LM.Reset then
            LM.Reset()
        end
        Core.Canvas = canvas
        Core.CanvasToken = canvasToken
    end
    return canvas
end
_G.MWHud = {
    GetCanvas = function()
        return Core.ResolveCanvas()
    end,
}
local function applyAimSettings()
    if (_G.MWConfig.MenuTuningRevision or 0) < 3 then
        _G.MWState.CustomTextData.AimTouchHipSpeed = 80
        _G.MWConfig.MenuTuningRevision = 3
        Core.SaveAfter = now() + 0.5
    end
    _G.MWConfig.ESPTextSize = 86
    _G.MWConfig.AimTouchShowFOV = false
    _G.MWConfig.AimTouchHipVisCheck = true
    _G.MWConfig.AimTouchScopeVisCheck = true
    _G.MWState.CustomTextData.AimTouchHipFOV = 100
    local speed = tonumber(_G.MWState.CustomTextData.AimTouchHipSpeed)
    _G.MWState.CustomTextData.AimTouchHipSpeed = finite(speed) and math.max(1, math.min(80, speed)) or 80
    local t = _G.MWState.CustomTextData
    local function bounded(value, low, high, fallback)
        value = tonumber(value)
        return finite(value) and math.floor(math.max(low, math.min(high, value)) + 0.5) or fallback
    end
    t.AimTarget = 2
    t.AimRecoilCompensation = 60
    t.IpadViewFOV = bounded(t.IpadViewFOV, 90, 120, 120)
    t.AimTouchHipBone, t.AimTouchScopeBone = 2, 2
    t.AimTouchScopeFOV = t.AimTouchHipFOV
    t.AimTouchScopeSpeed = t.AimTouchHipSpeed
    t.AimTouchHipDist = _G.MWConfig.EspMaxDistance
    t.AimTouchScopeDist = t.AimTouchHipDist
    _G.MWConfig.AimTouchScopeVisCheck = _G.MWConfig.AimTouchHipVisCheck
    _G.MWConfig.AimTouchScopeIgKnock = _G.MWConfig.AimTouchHipIgKnock
end

-- MODULE: runtime-recovery.lua
function Core.WidgetAttached(widget, parent)
    if not Valid(widget) then
        return false
    end
    local ok, attached = pcall(function()
        if type(widget.GetParent) == "function" then
            return objectToken(widget:GetParent()) == objectToken(parent)
        end
        return true -- Older bindings expose validity only.
    end)
    return ok and attached
end
local travel = { initialized = false }
function Core.ObserveContext(pc)
    local world
    if slua.getWorld then
        local ok, value = pcall(slua.getWorld)
        world = ok and value or nil
    end
    local controller = Valid(pc) and pc or nil
    local worldToken, pcToken = objectToken(world), objectToken(controller)
    local changed = travel.initialized and (worldToken ~= travel.worldToken or pcToken ~= travel.pcToken)
    if changed then
        Core.ResetViewportCache()
        safe("travel-clear", Core.Clear)
        safe("travel-menu", LM.Reset)
        safe("travel-crosshair", Core.RestoreCrosshair)
        safe("travel-ipad", Core.RestoreIpadView)
        if _G.XthrlenClearAimRuntime then
            safe("travel-aim", _G.XthrlenClearAimRuntime)
        end
        local launcher = Core.Launcher
        if launcher and Valid(launcher.root) then
            pcall(launcher.root.RemoveFromParent, launcher.root)
        end
        Core.Launcher, Core.Canvas, Core.ESPCanvas, Core.CanvasToken = nil, nil, nil, nil
        PlayerMapMarker.ESPCanvas = nil
        Core.NextCanvasCheck, Core.NextScan, Core.TransformAfter, Core.LastFrame = 0, 0, 0, 0
        Core.NextSkinPulse = 0
        Core.Pawns, Core.ActorRows, Core.VisibilityCache = {}, {}, {}
        Core.LOSMethod, Core.ViewFramePC = nil, nil
    end
    travel.initialized, travel.worldToken, travel.pcToken = true, worldToken, pcToken
end

function Core.StartWatchdog()
    local function arm()
        if not Core.Active or _G.SRCMinimal ~= Core then
            return
        end
        local ok, timer = pcall(Core.Ticker.AddTimerOnce, 2, function()
            Core.WatchdogTimer = nil
            if not Core.Active or _G.SRCMinimal ~= Core then
                return
            end
            safe("watchdog", function()
                if not LM.IsVerified() then
                    Core.Stop()
                elseif os.time() - (Core.LastCallback or os.time()) >= 6 then
                    Core.LastCallback = os.time()
                    Core.RearmFrame(0)
                end
            end)
            arm()
        end)
        if ok then
            Core.WatchdogTimer = timer
        else
            Core.Report("watchdog-timer", timer)
        end
    end
    Core.LastCallback = os.time()
    arm()
end

