            local cached_GameplayStatics = nil
            local cached_PlayerTombBox = nil
            local cached_ActorClass = nil
            _G.NeedCheckDeadBoxTimer = 0

            _G.DeadBox_TemperRequest = function(PlayerController)
                if not _G.NTHUY2004Config.SkinDeadBox or _G.NeedCheckDeadBoxTimer <= 0 then
                    return
                end

                local curTime = os.clock()
                if _G.LastCheckDeadBoxTime and (curTime - _G.LastCheckDeadBoxTime) < 2.0 then
                    return
                end
                _G.LastCheckDeadBoxTime = curTime
                _G.NeedCheckDeadBoxTimer = _G.NeedCheckDeadBoxTimer - 1

                local PlayerCharacter = PlayerController:GetPlayerCharacterSafety()
                if not slua.isValid(PlayerCharacter) then
                    return
                end

                if not cached_GameplayStatics then
                    cached_GameplayStatics = import("GameplayStatics")
                    cached_ActorClass = import("Actor")
                    cached_PlayerTombBox = import("PlayerTombBox")
                end

                if not _G.CachedActorArray_DB then
                    _G.CachedActorArray_DB = slua.Array(UEnums.EPropertyClass.Object, cached_ActorClass)
                end

                local UI_Util = require("client.common.ui_util")
                local GameInstance = UI_Util and UI_Util.GetGameInstance()
                if not GameInstance or not cached_GameplayStatics then
                    return
                end

                local myPlayerKey = PlayerController.PlayerKey
                local currentBoxSkinId = 0
                pcall(function()
                    local curVeh = PlayerCharacter.CurrentVehicle
                        or (
                            type(PlayerCharacter.GetCurrentVehicle) == "function"
                            and PlayerCharacter:GetCurrentVehicle()
                        )
                    if
                        slua.isValid(curVeh)
                        and _G.CurrentEquipVehicleID
                        and _G.CurrentEquipVehicleID ~= 0
                    then
                        currentBoxSkinId = tonumber(tostring(_G.CurrentEquipVehicleID) .. "1") or 0
                    else
                        local curWeapon = PlayerCharacter.GetCurrentWeapon
                                and PlayerCharacter:GetCurrentWeapon()
                            or PlayerCharacter.CurrentWeapon
                        if slua.isValid(curWeapon) then
                            local defineIDObj = curWeapon.GetItemDefineID and curWeapon:GetItemDefineID()
                            local curWeaponID = (defineIDObj and slua.isValid(defineIDObj))
                                    and defineIDObj.TypeSpecificID
                                or 0

                            if
                                curWeaponID > 0
                                and _G.AddOutfitLastAppliedSkin
                                and _G.AddOutfitLastAppliedSkin[curWeaponID]
                            then
                                local skinID = _G.AddOutfitLastAppliedSkin[curWeaponID]
                                if skinID and skinID > 1000000 then
                                    currentBoxSkinId = skinID
                                end
                            end
                        end
                    end
                end)

                if currentBoxSkinId == 0 then
                    return
                end

                local deadBoxes = cached_GameplayStatics.GetAllActorsOfClass(
                    GameInstance,
                    cached_PlayerTombBox,
                    _G.CachedActorArray_DB
                )
                if not deadBoxes then
                    return
                end

                local count = type(deadBoxes.Num) == "function" and deadBoxes:Num() or #deadBoxes
                for i = 1, count do
                    local deadBoxActor = type(deadBoxes.Get) == "function" and deadBoxes:Get(i - 1)
                        or deadBoxes[i]
                    if slua.isValid(deadBoxActor) and not deadBoxActor.bIsTDSkinApplied then
                        local damageCauser = deadBoxActor.DamageCauser

                        if slua.isValid(damageCauser) and damageCauser.PlayerKey == myPlayerKey then
                            local DeadBoxAvatarComponent = deadBoxActor.DeadBoxAvatarComponent_BP
                            if slua.isValid(DeadBoxAvatarComponent) then
                                pcall(function()
                                    DeadBoxAvatarComponent:ResetItemAvatar()
                                    DeadBoxAvatarComponent:PreChangeItemAvatar(currentBoxSkinId)
                                    DeadBoxAvatarComponent:SyncChangeItemAvatar(currentBoxSkinId)
                                end)
                                deadBoxActor.bIsTDSkinApplied = true
                            end
                        end
                    end
                end
            end

