                end
                slotID = slotID or F.resToCustSlot(resID)
                if not slotID then
                    return false
                end
                local comp = F.getAvatarComp2(char)
                if not comp then
                    return false
                end
                opts = opts or {}
                opts.allowPutOn = true
                local ok = F.setMakeSkin(comp, resID, slotID, opts)
                return ok
            end

