local Rows = {}
local function row(key, label, config, kind, minimum, maximum, textData)
    local target = textData and _G.MWState.CustomTextData or _G.MWConfig
    Rows[key] = {
        Key = key,
        Text = label,
        Kind = kind,
        MinValue = minimum,
        MaxValue = maximum,
        GetFunc = function()
            return target[config]
        end,
        SetFunc = function(_, value)
            if kind == "slider" then
                value = tonumber(value)
                if not finite(value) then
                    return false
                end
                value = math.floor(math.max(minimum, math.min(maximum, value)) + 0.5)
            else
                value = value == true or value == 1
            end
            local previous = target[config]
            target[config] = value
            if config == "SkinEnabled" and not Core.PreviewMode then
                local ok, err = Core.SetSkinEnabled(value)
                if not ok then
                    target[config] = previous
                    Core.Report("skin", err)
                    return false
                end
            elseif config:sub(1, 4) == "Skin" and not Core.PreviewMode then
                Core.ApplySkinSettings()
            end
            applyAimSettings()
            if config == "IpadView" or config == "IpadViewFOV" then
                if not Core.PreviewMode then
                    safe("ipad-view", Core.IpadViewTick, GameplayData.GetPlayerCharacter(), now(), true)
                end
            end
            Core.RequestSave()
            return true
        end,
    }
end
