local function check(x, y, on, list)
    LM.RoundRect(x, y, 44, 44, 13, on and purple or { 0.18, 0.16, 0.20, 1 }, 7, list)
    if not on then
        return
    end
    local short = LM.Rect(x + 11, y + 22, 11, 4, white, 8, list)
    local long = LM.Rect(x + 18, y + 30, 22, 4, white, 8, list)
    if short then
        short.w:SetRenderTransformPivot(FVector2D(0, 0.5))
        short.w:SetRenderAngle(42)
    end
    if long then
        long.w:SetRenderTransformPivot(FVector2D(0, 0.5))
        long.w:SetRenderAngle(-48)
    end
end
