function LM.BuildNav()
    if not login.verified or not LM.mainBuilt then
        return
    end
    LM.Clear(LM.nav)
    for i, section in ipairs(LM.Layout) do
        local yy = 212 + (i - 1) * 84
        local selected = i == LM.sec
        LM.RoundRect(
            50,
            yy,
            206,
            68,
            17,
            selected and { 0.17, 0.155, 0.14, 1 } or { 0.075, 0.066, 0.063, 1 },
            5,
            LM.nav
        )
        if selected then
            LM.RoundRect(64, yy + 18, 38, 34, 7, purple, 6, LM.nav)
        end
        LM.Text(
            string.format("%02d", i),
            83,
            yy + 35,
            12,
            selected and white or theme.tabText,
            0.5,
            0.5,
            8,
            LM.nav
        )
        LM.Text(section.name, 115, yy + 35, 18, white, 0, 0.5, 7, LM.nav)
        LM.Button(50, yy, 206, 68, 12, LM.nav, function()
            LM.sec = i
            LM.tab = 1
            LM.BuildNav()
            LM.BuildTabs()
            LM.BuildContent()
        end)
    end
