                    or lower:find("kar98", 1, true)
                    or lower:find("m24", 1, true)
                    or lower:find("awm", 1, true)
                    or lower:find("mosin", 1, true)
                    or lower:find("win94", 1, true)
                    or lower:find("amr", 1, true)
                    or lower:find("sks", 1, true)
                    or lower:find("slr", 1, true)
                    or lower:find("mini", 1, true)
                    or lower:find("mk14", 1, true)
                    or lower:find("qbu", 1, true)
                    or lower:find("mk12", 1, true)
                    or lower:find("vss", 1, true)
                )
            then
                kind = "SNIPER"
            end
            AIM_WEAPON_CACHE.Player, AIM_WEAPON_CACHE.WeaponKey = player, weaponKey
            AIM_WEAPON_CACHE.Kind, AIM_WEAPON_CACHE.Time = kind, now
            return kind, weapon
        end
        local function AimEnemyTargets(radius, pc, player, force)
            radius = tonumber(radius) or 0
            local now = _G.RealNow()
            local result = AIM_TARGET_CACHE.List
            if not Valid(player) then
                pc, player = AimPlayerContext()
            end
            if not Valid(player) then
                AimClear(result)
                return result
            end
            if
                not force
                and AIM_TARGET_CACHE.Pawn == player
                and AIM_TARGET_CACHE.Radius == radius
                and now - AIM_TARGET_CACHE.Time < 0.12
            then
                return AIM_TARGET_CACHE.List
            end
            AimClear(result)
            AimClear(AIM_ALL_SCRATCH)
            AimClear(AIM_SEEN_SCRATCH)
            ReuseCount("AimListRebuilds")
            local allChars, seen = AIM_ALL_SCRATCH, AIM_SEEN_SCRATCH
            local function AddCharacters(source)
                local function AddActor(actor)
                    local key = tostring(actor)
                    if Valid(actor) and not seen[key] then
                        seen[key] = true
                        allChars[#allChars + 1] = actor
                    end
                end
                if not source then
                    return
                end
                local count = nil
                pcall(function()
                    if type(source.Num) == "function" then
                        count = source:Num()
                    end
                end)
                if count then
                    for i = 0, count - 1 do
                        pcall(AddActor, source:Get(i))
                    end
                elseif type(source) == "table" then
                    for _, actor in pairs(source) do
                        AddActor(actor)
                    end
                end
            end
            local shared = false
            if _G.PlayerMapMarker and type(_G.PlayerMapMarker.GetAllCharacters) == "function" then
                local ok, list = pcall(_G.PlayerMapMarker.GetAllCharacters)
                if ok and list then
                    AddCharacters(list)
                    shared = true
                end
            end
            if not shared then
                pcall(function()
                    local game = rawget(_G, "Game")
                    if game and game.GetAllPlayerPawns then
                        AddCharacters(game:GetAllPlayerPawns())
                    end
                end)
                pcall(function()
                    if GameplayData.GetAllPlayerCharacters then
                        AddCharacters(GameplayData.GetAllPlayerCharacters())
                    end
                end)
                if #allChars <= 1 then
                    pcall(function()
                        local state = require("GameLua.GameCore.Data.CGameState")
                        if state and state.GetAllCharacters then
                            local ok, chars = pcall(state.GetAllCharacters, state)
                            if not ok then
                                ok, chars = pcall(state.GetAllCharacters)
                            end
                            if ok then
                                AddCharacters(chars)
                            end
                        end
                    end)
                end
                if GameplayData.GameCharacters then
                    AddCharacters(GameplayData.GameCharacters)
                end
            end
            local myTeam = player.TeamID
            pcall(function()
                if myTeam == nil and player.GetTeamID then
                    myTeam = player:GetTeamID()
                end
            end)
            for _, actor in pairs(allChars) do
                if Valid(actor) and actor ~= player then
                    local dead = false
                    pcall(function()
                        if type(actor.IsDead) == "function" then
                            dead = AimEnabled(actor:IsDead())
                        elseif type(actor.IsAlive) == "function" then
                            dead = not AimEnabled(actor:IsAlive())
                        else
                            dead = actor.bIsDead == true
                                or actor.bIsDeadFlag == true
                                or actor.HealthStatus == 2
                        end
                    end)
                    local team = actor.TeamID
                    pcall(function()
                        if team == nil and actor.GetTeamID then
                            team = actor:GetTeamID()
                        end
                    end)
                    local distance = math.huge
                    pcall(function()
                        if player.GetDistanceTo then
                            distance = player:GetDistanceTo(actor)
                        else
                            local a, b = player:K2_GetActorLocation(), actor:K2_GetActorLocation()
                            distance = math.sqrt((a.X - b.X) ^ 2 + (a.Y - b.Y) ^ 2 + (a.Z - b.Z) ^ 2)
                        end
                    end)
                    if
                        not dead
                        and (myTeam == nil or team == nil or team ~= myTeam)
                        and distance <= radius
                    then
                        result[#result + 1] = actor
                    end
                end
            end
            AimClear(allChars)
            AimClear(seen)
            AIM_TARGET_CACHE.Pawn = player
            AIM_TARGET_CACHE.Radius = radius
            AIM_TARGET_CACHE.Time = now
            return result
        end
        local AIM_VECTOR2D = rawget(_G, "FVector2D") or AimImport("Vector2D")
