        local function PruneAimVisCache(validList)
            local keep = AIM_KEEP_SCRATCH
            AimClear(keep)
            local now = _G.RealNow()
            if validList == AIM_TARGET_CACHE.List and now - (AIM_TARGET_CACHE.Time or 0) > 5 then
                AimClear(validList)
            end
            if now > (AIM_SELECTION_CACHE.Until or 0) + 5 then
                AIM_SELECTION_CACHE.Target = nil
            end
            if validList then
                for _, pawn in pairs(validList) do
                    if Valid(pawn) then
                        keep[GetSafeEnemyKey(pawn)] = true
                    end
                end
            end
            for key, record in pairs(AIM_VIS_CACHE) do
                if not keep[key] or now - (record.time or 0) > 5 then
                    AIM_VIS_CACHE[key] = nil
                end
            end
            for key, record in pairs(AIM_PROJECT_CACHE) do
                if not keep[key] or now - (record.Time or 0) > 5 then
                    AIM_PROJECT_CACHE[key] = nil
                end
            end
