            pcall(function()
                local ui = AIM_UI_UTIL or require("client.common.ui_util")
                AIM_UI_UTIL = ui
                if ui and ui.GetViewportSize then
                    local first, second = ui.GetViewportSize()
                    ReadSize(first, second)
                end
            end)
            if not size and Valid(pc) and type(pc.GetViewportSize) == "function" then
