            pcall(Accept, pc:ProjectWorldLocationToScreen(position, output, false))
            if not projected and AIM_GAMEPLAY and AIM_GAMEPLAY.ProjectWorldToScreen then
                pcall(Accept, AIM_GAMEPLAY.ProjectWorldToScreen(pc, position, output, false))
            end
