        local function AimTargetVisible(pc, target)
            if _G.MWLoS and _G.MWLoS.CachedVisible then
                local ok, value = pcall(function()
                    local own = (_G.XthrlenNeonOverlayContext or {}).Player
                    if not own and type(pc.GetPlayerCharacterSafety) == "function" then
                        own = pc:GetPlayerCharacterSafety()
                    end
                    if not own and type(pc.GetPawn) == "function" then
                        own = pc:GetPawn()
                    end
                    return _G.MWLoS.CachedVisible(target, pc, own)
                end)
                if ok then
                    return value == true or value == 1
                end
            end
            local key = GetSafeEnemyKey(target)
            local now = _G.RealNow()
            local cached = AIM_VIS_CACHE[key]
            if cached and cached.Actor == target and cached.PC == pc and now - cached.time < 0.20 then
                return cached.visible
            end
            local visible = false
            local tried = false
            local function try(fn)
                if tried and visible then
                    return
                end
                local ok, res = pcall(fn)
                if ok and (res == true or res == 1) then
                    visible = true
                    tried = true
                elseif ok and (res == false or res == 0) then
                    tried = true
                end
            end
            try(function()
                return pc:LineOfSightTo(target, nil, false)
            end)
            if not tried then
                try(function()
                    return pc:LineOfSightTo(target)
                end)
            end
            if not tried and type(pc.K2_LineOfSightTo) == "function" then
                try(function()
                    return pc:K2_LineOfSightTo(target)
                end)
            end
            if not tried and type(pc.HasLineOfSightTo) == "function" then
                try(function()
                    return pc:HasLineOfSightTo(target)
                end)
            end
            if not tried and cached then
                visible = cached.visible
            end
            if not cached then
                cached = {}
                AIM_VIS_CACHE[key] = cached
                ReuseCount("AimVisibilityCreated")
            end
            cached.Actor, cached.PC = target, pc
            cached.visible, cached.time = visible, now
            return visible
        end
        local function AimMortarPitch(origin, target)
            if not origin or not target then
                return nil
            end
            local horizontal = math.sqrt((target.X - origin.X) ^ 2 + (target.Y - origin.Y) ^ 2) - 80
            if horizontal < 500 then
                horizontal = 500
            end
            local vertical = target.Z - origin.Z
            local function Solve(speed, gravity)
                local speed2 = speed * speed
                local discriminant = speed2 * speed2
                    - gravity * (gravity * horizontal * horizontal + 2 * vertical * speed2)
                if discriminant < 0 then
                    return nil
                end
                local angle = math.atan((speed2 + math.sqrt(discriminant)) / (gravity * horizontal))
                local degrees = math.deg(angle)
                if degrees < 35 or degrees > 89.5 then
                    return nil
                end
                return degrees
            end
            local distance = horizontal
            local angle = Solve(9070, 980 * 2.8)
            if not angle or distance > 25000 then
                angle = Solve(12520, 980 * 4.0)
                if not angle or distance > 40000 then
                    angle = Solve(16800, 980 * 4.5)
                end
            end
            if not angle then
                angle = Solve(9070, 980 * 2.8)
            end
            if not angle then
                return nil
            end
            return ((angle - 45) / 43.0) * 90.0 - 60.0
        end
        _G.XthrlenBulletSpeedCache = {}
        function _G.XthrlenBulletSpeed(weapon, kind)
            if not weapon then
                return 900
            end
            local key = tostring(weapon)
            local cache = _G.XthrlenBulletSpeedCache
            local hit = cache[key]
            if hit then
                return hit
            end
            local speed = nil
            if type(weapon.GetBulletFireSpeedFromEntity) == "function" then
                local ok, v = pcall(weapon.GetBulletFireSpeedFromEntity, weapon)
                if ok then
                    speed = tonumber(v)
                end
            end
            if not speed then
                local comp = weapon.AttrModifierCompoment or weapon.AttrModifyComponent
                if comp and type(comp.GetAttributeValue) == "function" then
                    local ok, v = pcall(comp.GetAttributeValue, comp, "BulletFireSpeed")
                    if ok then
                        speed = tonumber(v)
                    end
                end
            end
            if not speed then
                local ok, v = pcall(function()
                    return weapon.BulletFireSpeed
                end)
                if ok then
                    speed = tonumber(v)
                end
            end
            if not speed or speed < 30 or speed > 300000 then
                if kind == "SNIPER" then
                    speed = 90000
                elseif kind == "MORTAR" then
                    speed = 10000
                elseif kind == "SHOTGUN" then
                    speed = 37000
                else
                    speed = 88000
                end
            end
            if speed > 2000 then
                speed = speed / 100
            end
            cache[key] = speed
            return speed
        end
        function _G.XthrlenAimLead(target, origin, aim, predVal, weapon, kind)
            local px, py, pz = tonumber(aim.X) or 0, tonumber(aim.Y) or 0, tonumber(aim.Z) or 0
            if not Valid(target) then
                return px, py, pz
            end
            local okV, vel = pcall(target.GetVelocity, target)
            if not okV or not vel then
                return px, py, pz
            end
            local vx, vy, vz = tonumber(vel.X) or 0, tonumber(vel.Y) or 0, tonumber(vel.Z) or 0
            local moving = not (vx == 0 and vy == 0 and vz == 0)
            if not moving then
                return px, py, pz
            end
            local ox = tonumber(origin.X) or px
            local oy = tonumber(origin.Y) or py
            local oz = tonumber(origin.Z) or pz
            local speed = _G.XthrlenBulletSpeed(weapon, kind)
            if speed < 40 then
                speed = 40
            end
            local strength = predVal / 50.0
            if strength < 0 then
                strength = 0
            elseif strength > 2 then
                strength = 2
            end
            local ax, ay, az = px, py, pz
            for _ = 1, 3 do
                local dx, dy, dz = ax - ox, ay - oy, az - oz
                local dist = math.sqrt(dx * dx + dy * dy + dz * dz) / 100.0
                local tof = dist / speed
                if tof < 0 then
                    tof = 0
                elseif tof > 3 then
                    tof = 3
                end
                ax = px + vx * tof * strength
                ay = py + vy * tof * strength
                az = pz + vz * tof * strength
            end
            return ax, ay, az
        end
        local AIM_SHOT_TOKEN = {}
        _G.AimTouch = function(resolvedPC, resolvedPlayer, resolvedLobby, shotToken)
            _G.MWState.AimLineScreenPos = nil
            _G.MWState.AimTouchTarget = nil
            _G.MWState.AimTouchAimPos = nil
            _G.MWState.AimTouchAimPosRaw = nil
            DiagStage("AimTouch.enter")
            if not DiagAllowed("Aim") then
                if _G.XthrlenClearAimRuntime then
                    pcall(_G.XthrlenClearAimRuntime)
                end
                return
            end
            local requestAutoFire = false
            local manualShot = shotToken == AIM_SHOT_TOKEN
            if manualShot then
                _G.MWState.AimLastShotStatus = "entered"
            end
            local success, aimError = pcall(function()
                if not AimEnabled(_G.MWConfig.AimTouchEnable) then
                    return
                end
                local sgAutoFire = not manualShot and AimEnabled(_G.MWConfig.AimTouchSGAutoFire)
                local pc, player, inLobby =
                    resolvedPC, resolvedPlayer, (resolvedLobby == true or resolvedLobby == 1)
                if not Valid(pc) or not Valid(player) then
                    pc, player, inLobby = AimPlayerContext()
                end
                if inLobby or not Valid(player) or not Valid(pc) then
                    return
                end
                if AIM_LAST_PLAYER ~= player then
                    ClearAimRuntime()
                end
                AIM_LAST_PLAYER = player
                _G.MWState.CustomTextData = _G.MWState.CustomTextData or {}
                local isFiring = manualShot
                    or AimEnabled(player.bIsWeaponFiring)
                    or AimEnabled(player.bIsFiring)
                    or AimEnabled(player.bIsFiringADS)
                local isADS = AimIsADS(player)
                local weaponKind, weapon = AimWeaponKind(player)
                local isSG = weaponKind == "SHOTGUN"
                local isSniper = weaponKind == "SNIPER"
                local isMortar = weaponKind == "MORTAR"
                local sgPreAim = isSG
                    and AimEnabled(_G.MWConfig.AimTouchSG)
                    and not sgAutoFire
                    and not AimEnabled(_G.MWConfig.AimTouchSGOnlyFire)
                    and not isFiring
                local currentAmmo = AimShotgunAmmo(weapon)
                if isSG and sgAutoFire and currentAmmo == nil then
                    _G.MWState.AimAutoFireStatus = "ammo_unavailable"
                    return
                end
                currentAmmo = currentAmmo or 1
                if isSG and currentAmmo <= 0 and not manualShot then
                    return
                end
                local cond, prioMode, boneIdx = 2, 1, 1
                local speedVal, fovVal, maxDistMeters = 50, 30, 50
                local useVisCheck, igKnock, igBot = false, false, false
                local predVal, recoilCompVal = 0, 0
                local branchActive = false
                local scopedBranch = false
                local shotgunBranch = false
                if isMortar and AimEnabled(_G.MWConfig.AimTouchMortar) then
                    local deployed = false
                    pcall(function()
                        deployed = weapon and weapon.MortarState == 2
                    end)
                    if not deployed then
                        return
                    end
                    branchActive = true
                    cond = 2
                    prioMode = 1
                    boneIdx = 4
                    speedVal = 30
                    fovVal = (_G.MWState.CustomTextData or {}).AimTouchMortarFOV or 360
                    maxDistMeters = 2000
                    predVal = (_G.MWState.CustomTextData or {}).AimTouchMortarPred or 0
                elseif isSG and AimEnabled(_G.MWConfig.AimTouchSG) then
                    branchActive = true
                    shotgunBranch = true
                    cond = _G.MWState.CustomTextData.AimTouchSGCond or 1
                    if sgAutoFire then
                        cond = 2
                    end
                    prioMode = _G.MWState.CustomTextData.AimTouchSGPrio or 1
                    boneIdx = _G.MWState.CustomTextData.AimTouchSGBone or 2
                    speedVal = _G.MWState.CustomTextData.AimTouchSGSpeed or 80
                    fovVal = _G.MWState.CustomTextData.AimTouchSGFOV or 40
                    maxDistMeters = _G.MWState.CustomTextData.AimTouchSGDist or 30
                    useVisCheck = AimEnabled(_G.MWConfig.AimTouchSGVisCheck)
                    igKnock = AimEnabled(_G.MWConfig.AimTouchSGIgKnock)
                    igBot = AimEnabled(_G.MWConfig.AimTouchSGIgBot)
                elseif isADS then
                    scopedBranch = true
                    if isSniper and AimEnabled(_G.MWConfig.AimTouchScopeSniper) then
                        branchActive = true
                        cond = 2
                        prioMode = _G.MWState.CustomTextData.AimTouchSniperPrio or 1
                        boneIdx = _G.MWState.CustomTextData.AimTouchSniperBone or 1
                        speedVal = _G.MWState.CustomTextData.AimTouchSniperSpeed or 30
                        fovVal = _G.MWState.CustomTextData.AimTouchSniperFOV or 20
                        maxDistMeters = _G.MWState.CustomTextData.AimTouchSniperDist or 400
                        useVisCheck = AimEnabled(_G.MWConfig.AimTouchSniperVisCheck)
                        igKnock = AimEnabled(_G.MWConfig.AimTouchSniperIgKnock)
                        igBot = AimEnabled(_G.MWConfig.AimTouchSniperIgBot)
                        predVal = (_G.MWState.CustomTextData or {}).AimTouchSniperPred or 0
                    elseif AimEnabled(_G.MWConfig.AimTouchScopeAll) then
                        branchActive = true
                        cond = _G.MWState.CustomTextData.AimTouchScopeCond or 1
                        prioMode = _G.MWState.CustomTextData.AimTouchScopePrio or 1
                        boneIdx = _G.MWState.CustomTextData.AimTouchScopeBone or 2
                        speedVal = _G.MWState.CustomTextData.AimTouchScopeSpeed or 40
                        fovVal = _G.MWState.CustomTextData.AimTouchScopeFOV or 20
                        maxDistMeters = _G.MWState.CustomTextData.AimTouchScopeDist or 300
                        useVisCheck = AimEnabled(_G.MWConfig.AimTouchScopeVisCheck)
                        igKnock = AimEnabled(_G.MWConfig.AimTouchScopeIgKnock)
                        igBot = AimEnabled(_G.MWConfig.AimTouchScopeIgBot)
                        predVal = (_G.MWState.CustomTextData or {}).AimTouchScopePred or 0
                        recoilCompVal = (_G.MWState.CustomTextData or {}).AimTouchScopeRecoil or 0
                    end
                else
                    if AimEnabled(_G.MWConfig.AimTouchHipfire) then
                        branchActive = true
                        cond = _G.MWState.CustomTextData.AimTouchHipCond or 1
                        prioMode = _G.MWState.CustomTextData.AimTouchHipPrio or 1
                        boneIdx = _G.MWState.CustomTextData.AimTouchHipBone or 1
                        speedVal = _G.MWState.CustomTextData.AimTouchHipSpeed or 50
                        fovVal = _G.MWState.CustomTextData.AimTouchHipFOV or 30
                        maxDistMeters = _G.MWState.CustomTextData.AimTouchHipDist or 250
                        useVisCheck = _G.MWConfig.AimTouchHipVisCheck
                        igKnock = _G.MWConfig.AimTouchHipIgKnock
                        igBot = _G.MWConfig.AimTouchHipIgBot
                    end
                end
                _G.MWState.ActiveFOVVal = fovVal
                if not branchActive then
                    return
                end
                local aimAllowed
                if shotgunBranch then
                    aimAllowed = sgAutoFire or not AimEnabled(_G.MWConfig.AimTouchSGOnlyFire) or isFiring
                elseif scopedBranch then
                    aimAllowed = tonumber(cond) == 2 or isFiring
                else
                    aimAllowed = not (
                        (not isMortar and not isSG and not isFiring) or (cond == 1 and not isFiring)
                    )
                end
                if not aimAllowed then
                    if shotgunBranch then
                        _G.MWState.AimTouchTarget = nil
                        _G.MWState.AimTouchAimPos = nil
                        _G.MWState.AimLineScreenPos = nil
                    end
                    return
                end
                local curTime = _G.RealNow()
                local softAim = (isSG and (sgAutoFire or sgPreAim)) or isMortar
                if softAim then
                    local control = pc:GetControlRotation()
                    if not control then
                        return
                    end
                    local state = _G.MWState.AimSoftControl
                    if not state then
                        state = {}
                        _G.MWState.AimSoftControl = state
                    end
                    if
                        state.Pawn ~= player
                        or state.Weapon ~= weapon
                        or curTime - (state.Time or -1) > 0.25
                    then
                        state.Yaw = nil
                        state.PauseUntil = 0
                    end
                    if state.Yaw then
                        local yaw = (control.Yaw - state.Yaw + 180) % 360 - 180
                        local pitch = (control.Pitch - state.Pitch + 180) % 360 - 180
                        local yawGate = isSG and 3.0 or 0.12
                        local pitchGate = isSG and 2.0 or 0.12
                        if math.abs(yaw) > yawGate or math.abs(pitch) > pitchGate then
                            state.PauseUntil = curTime + (isSG and 0.06 or 0.18)
                            AIM_SELECTION_CACHE.Target = nil
                            AIM_SELECTION_CACHE.Until = 0
                            _G.MWState.PrevAimTarget = nil
                        end
                    end
                    state.Pawn, state.Weapon, state.Time = player, weapon, curTime
                    state.Yaw, state.Pitch = control.Yaw, control.Pitch
                    if curTime < (state.PauseUntil or 0) then
                        return
                    end
                else
                    _G.MWState.AimSoftControl = nil
                end
                local currentMaxDist = maxDistMeters * 100
                local UG, KML = AIM_GAMEPLAY, AIM_MATH
                local camMgr = pc.PlayerCameraManager
                pcall(function()
                    if not Valid(camMgr) and type(pc.GetPlayerCameraManager) == "function" then
                        camMgr = pc:GetPlayerCameraManager()
                    end
                    if not Valid(camMgr) and UG and UG.GetPlayerCameraManager then
                        camMgr = UG.GetPlayerCameraManager(pc, 0)
                    end
                end)
                if not slua.isValid(camMgr) then
                    if manualShot then
                        _G.MWState.AimLastShotStatus = "camera_missing"
                    end
                    return
                end
                local camLoc = camMgr:GetCameraLocation()
                if not camLoc then
                    return
                end
                local vp = AimViewportSize(pc)
                if not vp then
                    if manualShot then
                        _G.MWState.AimLastShotStatus = "viewport_missing"
                    end
                    return
                end
                local cX, cY = vp.X * 0.5, vp.Y * 0.5
                local FOV_RADIUS = (fovVal / 100.0) * (vp.X / 2.0)
                local selBone = "head"
                if boneIdx == 1 then
                    selBone = "head"
                elseif boneIdx == 2 then
                    selBone = "spine_03"
                elseif boneIdx == 3 then
                    selBone = "spine_01"
                elseif boneIdx == 4 then
                    selBone = "pelvis"
                elseif boneIdx == 5 then
                    selBone = "neck_01"
                elseif boneIdx == 6 then
                    selBone = "calf_l"
                end
                local bestTarget, bestPosition, bestScore = nil, nil, 99999999
                local bestScreenDist = nil
                local bestScreenXY = nil
                local fireGatePx = FOV_RADIUS * 0.28
                if fireGatePx < 18 then
                    fireGatePx = 18
                elseif fireGatePx > 55 then
                    fireGatePx = 55
                end
                if isSG and sgAutoFire then
                    fireGatePx = math.max(8, math.min(18, FOV_RADIUS * 0.06))
                end
                local function _storeBestScreen(pos)
                    if not pos then
                        return
                    end
                    local tmp = AIM_VECTOR2D and AIM_VECTOR2D(0, 0) or { X = 0, Y = 0 }
                    if AimProject(pc, pos, tmp) then
                        bestScreenDist =
                            math.sqrt((tmp.X - cX) * (tmp.X - cX) + (tmp.Y - cY) * (tmp.Y - cY))
                        bestScreenXY = { X = tmp.X, Y = tmp.Y }
                    end
                end
                local screen = AIM_VECTOR2D and AIM_VECTOR2D(0, 0) or { X = 0, Y = 0 }
                local selectionKey = nil
                local projectBudget = 64
                local projectCacheTTL = (manualShot or scopedBranch or sgPreAim) and 0 or 0.12
                local function Candidate(target, validateWorld)
                    if not Valid(target) or target == player then
                        return nil
                    end
                    if
                        target.HealthStatus == 2
                        or AimEnabled(target.bIsDead)
                        or AimEnabled(target.bIsDeadFlag)
                    then
                        return nil
                    end
                    if igKnock and target.HealthStatus == 1 then
                        return nil
                    end
                    if igBot then
                        local bot = false
                        if _G.PlayerMapMarker and _G.PlayerMapMarker.IsAI then
                            local ok, value = pcall(_G.PlayerMapMarker.IsAI, target)
                            bot = ok and value == true
                        else
                            bot = AimEnabled(target.bIsAI)
                                or AimEnabled(target.IsAI)
                                or AimEnabled(target.bEnsure)
                            local ps = target.PlayerState
                            if Valid(ps) then
                                bot = bot or AimEnabled(ps.bIsABot) or AimEnabled(ps.bIsBot)
                            end
                        end
                        if bot then
                            return nil
                        end
                    end
                    local worldDistance = nil
                    if validateWorld or prioMode == 2 then
                        worldDistance = tonumber(player:GetDistanceTo(target)) or math.huge
                        if validateWorld and worldDistance > currentMaxDist then
                            return nil
                        end
                    end
                    if validateWorld then
                        local myTeam, targetTeam = tonumber(player.TeamID), tonumber(target.TeamID)
                        if myTeam and targetTeam and myTeam > 0 and myTeam == targetTeam then
                            return nil
                        end
                    end
                    local position = AimBoneLocation(target, selBone, boneIdx)
                    if not position or (position.X == 0 and position.Y == 0 and position.Z == 0) then
                        return nil
                    end
                    local targetKey = GetSafeEnemyKey(target)
                    local cached = AIM_PROJECT_CACHE[targetKey]
                    if
                        not validateWorld
                        and cached
                        and cached.Selection == selectionKey
                        and cached.Bone == selBone
                        and curTime - (cached.Time or 0) < projectCacheTTL
                    then
                        screen.X, screen.Y = cached.X, cached.Y
                        if cached.Ok == false then
                            return nil
                        end
                    else
                        if not validateWorld and projectBudget <= 0 then
                            return nil
                        end
                        if not validateWorld then
                            projectBudget = projectBudget - 1
                        end
                        local okProject = AimProject(pc, position, screen)
                        if not cached then
                            cached = {}
                            AIM_PROJECT_CACHE[targetKey] = cached
                            ReuseCount("AimProjectionCreated")
                        else
                            ReuseCount("AimProjectionReused")
                        end
                        cached.Ok, cached.X, cached.Y, cached.Time =
                            okProject, screen.X, screen.Y, curTime
                        cached.Selection, cached.Bone = selectionKey, selBone
                        if not okProject then
                            return nil
                        end
                    end
                    if screen.X <= 0 or screen.Y <= 0 then
                        return nil
                    end
                    local dx, dy = screen.X - cX, screen.Y - cY
                    local distanceScreen = math.sqrt(dx * dx + dy * dy)
                    if distanceScreen > FOV_RADIUS then
                        return nil
                    end
                    local score = distanceScreen
                    if prioMode == 2 then
                        score = worldDistance
                    elseif prioMode == 3 then
                        score = target.Health or 100
                    elseif prioMode == 4 then
                        local hp, mx = target.Health or 100, target.HealthMax or 100
                        if mx <= 0 then
                            mx = 100
                        end
                        score = hp / mx
                    end
                    if useVisCheck then
                        if shotgunBranch then
                            local los = _G.MWLoS
                            if not los or type(los.PointVisible) ~= "function" then
                                return nil
                            end
                            local checked, visible =
                                pcall(los.PointVisible, pc, target, player, camLoc, position)
                            if not checked or visible ~= true then
                                return nil
                            end
                        elseif not AimTargetVisible(pc, target) then
                            return nil
                        end
                    end
                    return score, position
                end
                local weaponKey = AIM_WEAPON_CACHE.WeaponKey or tostring(weapon)
                local selection = AIM_SELECTION_CACHE
                if
                    not selection.ConfigKey
                    or selection.KeyWeapon ~= weaponKey
                    or selection.KeyKind ~= weaponKind
                    or selection.KeyBone ~= boneIdx
                    or selection.KeyPrio ~= prioMode
                    or selection.KeyFOV ~= fovVal
                    or selection.KeyDistance ~= maxDistMeters
                    or selection.KeyVis ~= useVisCheck
                    or selection.KeyKnock ~= igKnock
                    or selection.KeyBot ~= igBot
                    or selection.KeyADS ~= isADS
                then
                    selection.ConfigKey = weaponKey
                        .. ":"
                        .. weaponKind
                        .. ":"
                        .. boneIdx
                        .. ":"
                        .. prioMode
                        .. ":"
                        .. fovVal
                        .. ":"
                        .. maxDistMeters
                        .. ":"
                        .. tostring(useVisCheck)
                        .. ":"
                        .. tostring(igKnock)
                        .. ":"
                        .. tostring(igBot)
                        .. ":"
                        .. tostring(isADS)
                    selection.KeyWeapon, selection.KeyKind, selection.KeyBone, selection.KeyPrio =
                        weaponKey, weaponKind, boneIdx, prioMode
                    selection.KeyFOV, selection.KeyDistance, selection.KeyVis =
                        fovVal, maxDistMeters, useVisCheck
                    selection.KeyKnock, selection.KeyBot, selection.KeyADS = igKnock, igBot, isADS
                    ReuseCount("AimConfigKeyBuilds")
                else
                    ReuseCount("AimConfigKeyReuses")
                end
                selectionKey = selection.ConfigKey
                local reuse = not manualShot
                    and selection.Pawn == player
                    and selection.Key == selectionKey
                    and curTime < (selection.Until or 0)
                if reuse and selection.Target == false then
                    return
                end
                if reuse and Valid(selection.Target) then
                    local ok, score, position = pcall(Candidate, selection.Target, true)
                    if ok and score then
                        bestTarget, bestScore, bestPosition = selection.Target, score, position
                    end
                end
                if not bestTarget then
                    local enemies = AimEnemyTargets(currentMaxDist, pc, player, manualShot)
                    local candidateList = enemies or {}
                    if #candidateList > 24 then
                        AIM_SCRATCH_USED = true
                        local ranked = AIM_RANK_SCRATCH
                        AimClear(ranked)
                        for index, target in ipairs(candidateList) do
                            local row = AIM_RANK_ROWS[index]
                            if not row then
                                row = {}
                                AIM_RANK_ROWS[index] = row
                                ReuseCount("AimRankRowCreated")
                            end
                            row.target, row.order, row.dist = target, index, math.huge
                            row.dist = _G.XthrlenAimDistTo(player, target)
                            ranked[index] = row
                        end
                        for i = #candidateList + 1, #AIM_RANK_ROWS do
                            AIM_RANK_ROWS[i].target = nil
                        end
                        table.sort(ranked, AimRankLess)
                        local capped = AIM_CANDIDATE_SCRATCH
                        AimClear(capped)
                        for i = 1, math.min(24, #ranked) do
                            capped[i] = ranked[i].target
                        end
                        candidateList = capped
                    end
                    if #candidateList > 16 then
                        AIM_SCRATCH_USED = true
                        local start = ((selection.Cursor or 0) % #candidateList) + 1
                        selection.Cursor = start
                        local rotated = AIM_ROTATE_SCRATCH
                        AimClear(rotated)
                        for offset = 0, #candidateList - 1 do
                            rotated[#rotated + 1] =
                                candidateList[((start + offset - 1) % #candidateList) + 1]
                        end
                        candidateList = rotated
                    end
                    projectBudget = #candidateList > 16 and 16 or #candidateList
                    for _, target in ipairs(candidateList) do
                        local ok, score, position = pcall(Candidate, target, false)
                        if ok and score and score < bestScore then
                            bestTarget, bestScore, bestPosition = target, score, position
                        end
                    end
                    selection.Pawn, selection.Key = player, selectionKey
                    selection.Target, selection.Until =
                        bestTarget or false, curTime + (bestTarget and 0.10 or 0.016)
                end
                if not slua.isValid(bestTarget) then
                    if manualShot then
                        _G.MWState.AimLastShotStatus = "no_target_in_fov"
                    end
                    return
                end
                if _G.MWState.PrevAimTarget ~= bestTarget then
                    _G.MWState.PrevAimTarget = bestTarget
                    _G.MWState.PrevAimTargetTime = curTime
                end
                if bestScreenDist == nil and bestPosition then
                    _storeBestScreen(bestPosition)
                end
                local fb = bestPosition or AimBoneLocation(bestTarget, selBone, boneIdx)
                if not fb or (fb.X == 0 and fb.Y == 0 and fb.Z == 0) then
                    return
                end
                if shotgunBranch and useVisCheck then
                    local los = _G.MWLoS
                    local checked, visible = pcall(los.PointVisible, pc, bestTarget, player, camLoc, fb)
                    if not checked or visible ~= true then
                        AIM_SELECTION_CACHE.Target = nil
                        return
                    end
                end
                _G.MWState.AimTouchTarget = bestTarget
                local raw = _G.MWState._AimRawBuffer or {}
                _G.MWState._AimRawBuffer = raw
                raw.X, raw.Y, raw.Z = fb.X, fb.Y, fb.Z
                _G.MWState.AimTouchAimPosRaw = raw
                if predVal > 0 then
                    local lx, ly, lz =
                        _G.XthrlenAimLead(bestTarget, camLoc, fb, predVal, weapon, weaponKind)
                    fb.X, fb.Y, fb.Z = lx, ly, lz
                end
                local final = _G.MWState._AimFinalBuffer or {}
                _G.MWState._AimFinalBuffer = final
                final.X, final.Y, final.Z = fb.X, fb.Y, fb.Z
                _G.MWState.AimTouchAimPos = final
                -- OLD LUA FILE.LUA applies distance-scaled height correction only while ADS firing.
                local compensation = _G.MWState.CustomTextData.AimRecoilCompensation or 0
                if not isMortar and isADS and isFiring and compensation > 0 then
                    local distance = player:GetDistanceTo(bestTarget) / 100.0
                    if finite(distance) and distance >= 0 then
                        fb.Z = fb.Z - distance * Core.AimRecoilHeightPerMeter * (compensation / 50.0)
                        final.Z = fb.Z
                    end
                end
                local rot = KML.FindLookAtRotation(camLoc, fb)
                if not rot then
                    return
                end
                local cur = pc:GetControlRotation()
                if not cur then
                    return
                end
                local dy = rot.Yaw - cur.Yaw
                local dp = rot.Pitch - cur.Pitch
                if isADS and type(camMgr.GetCameraRotation) == "function" then
                    pcall(function()
                        local cameraRot = camMgr:GetCameraRotation()
                        if cameraRot then
                            dy = dy - ((cameraRot.Yaw - cur.Yaw + 180) % 360 - 180)
                            dp = dp - ((cameraRot.Pitch - cur.Pitch + 180) % 360 - 180)
                        end
                    end)
                end
                dy = (dy + 180) % 360 - 180
                dp = (dp + 180) % 360 - 180
                local sf = 0.0
                if (isSG and not sgAutoFire and not sgPreAim) or (speedVal >= 100 and not softAim) then
                    sf = 1.0
                else
                    local dt = tonumber(_G.MWState.AimFrameDelta) or 1 / 60
                    if dt ~= dt or dt <= 0 then
                        dt = 1 / 60
                    end
                    dt = math.min(dt, 1 / 15)
                    local alpha = math.max(0.01, math.min(0.3, (speedVal / 100.0) * 0.3))
                    if isSG and softAim then
                        alpha = math.max(0.03, math.min(0.75, (speedVal / 100.0) * 0.60))
                    elseif softAim then
                        alpha = math.min(alpha, isMortar and 0.09 or 0.24)
                    end
                    sf = 1 - (1 - alpha) ^ (dt * 60)
                end
                local finalPitch = cur.Pitch + (dp * sf)
                if isMortar and AimEnabled(_G.MWConfig.AimTouchMortar) then
                    local origin = camLoc
                    pcall(function()
                        local actorLoc = player:K2_GetActorLocation()
                        if actorLoc then
                            origin = { X = actorLoc.X, Y = actorLoc.Y, Z = actorLoc.Z + 50 }
                        end
                    end)
                    local mortarPitch = AimMortarPitch(origin, fb)
                    if mortarPitch then
                        local delta = mortarPitch - cur.Pitch
                        if delta > 180 then
                            delta = delta - 360
                        elseif delta < -180 then
                            delta = delta + 360
                        end
                        finalPitch = cur.Pitch + (delta * sf)
                    end
                end
                if recoilCompVal > 0 and isFiring then
                    finalPitch = finalPitch - ((recoilCompVal / 50.0) * 1.5)
                end
                local rotation = _G.MWState._AimRotationBuffer
                if not rotation then
                    rotation = FRotator and FRotator(0, 0, 0) or { Pitch = 0, Yaw = 0, Roll = 0 }
                    _G.MWState._AimRotationBuffer = rotation
                end
                rotation.Pitch, rotation.Yaw, rotation.Roll = finalPitch, cur.Yaw + (dy * sf), 0
                local rotated, rotationResult = pcall(pc.SetControlRotation, pc, rotation, "AimTouch")
                if not rotated or rotationResult == false then
                    rotated, rotationResult = pcall(pc.SetControlRotation, pc, rotation)
                end
                if not rotated or rotationResult == false then
                    error("control_rotation_rejected:" .. tostring(rotationResult))
                end
                if softAim then
                    local state = _G.MWState.AimSoftControl
                    if state then
                        state.Yaw, state.Pitch = rotation.Yaw, rotation.Pitch
                    end
                end
                if manualShot then
                    _G.MWState.AimLastShotStatus = "rotated"
                end
                local canFireNow = true
                if isSG and sgAutoFire then
                    local boneDist
                    pcall(function()
                        local point = AIM_VECTOR2D and AIM_VECTOR2D(0, 0) or { X = 0, Y = 0 }
                        if AimProject(pc, fb, point) then
                            boneDist = math.sqrt((point.X - cX) ^ 2 + (point.Y - cY) ^ 2)
                        end
                    end)
                    if not boneDist or boneDist > fireGatePx then
                        canFireNow = false
                    end
                end
                if isSG and sgAutoFire then
                    if not canFireNow then
                        StopAimAutoFire(player)
                    else
                        local current = type(player.GetCurrentWeapon) == "function"
                                and player:GetCurrentWeapon()
                            or weapon
                        if not Valid(current) then
                            current = weapon
                        end
                        requestAutoFire = AimStepShotgunAutoFire(player, pc, current)
